INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
-- Prüfung 1: Planen eines Softwareprodukts > Design Pattern > Model View Presenter (MVP)
-- Ja/Nein-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Ist im MVP-Muster die View immer direkt mit dem Model verbunden?', 2, '[{"text": "Nein", "correct": true, "because": "Der Presenter vermittelt zwischen View und Model"}, {"text": "Ja", "correct": false, "because": "Direkte Verbindung widerspricht MVP"}]'),
('00000000-0000-0000-0000-000000000000', 'Kann der Presenter im MVP-Muster die Geschäftslogik enthalten?', 2, '[{"text": "Ja", "correct": true, "because": "Der Presenter verarbeitet oft die Logik"}, {"text": "Nein", "correct": false, "because": "Logik ist typisch für den Presenter"}]'),
('00000000-0000-0000-0000-000000000000', 'Muss die View im MVP-Muster immer passiv sein?', 2, '[{"text": "Ja", "correct": true, "because": "Die View reagiert nur auf Anweisungen des Presenters"}, {"text": "Nein", "correct": false, "because": "Aktive Views widersprechen MVP"}]'),
('00000000-0000-0000-0000-000000000000', 'Kann das MVP-Muster ohne eine grafische Benutzeroberfläche verwendet werden?', 2, '[{"text": "Nein", "correct": true, "because": "MVP ist auf UI-Anwendungen ausgelegt"}, {"text": "Ja", "correct": false, "because": "UI ist zentral für MVP"}]'),
('00000000-0000-0000-0000-000000000000', 'Ist das MVP-Muster immer komplexer als das MVC-Muster?', 2, '[{"text": "Nein", "correct": true, "because": "Komplexität hängt vom Einsatz ab"}, {"text": "Ja", "correct": false, "because": "Nicht zwangsläufig komplexer"}]'),

-- Single-Choice-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Welche Komponente im MVP-Muster steuert die Interaktion zwischen View und Model?', 2, '[{"text": "Presenter", "correct": true, "because": "Der Presenter vermittelt und steuert"}, {"text": "View", "correct": false, "because": "View ist passiv"}, {"text": "Model", "correct": false, "because": "Model enthält Daten"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Aufgabe hat die View im MVP-Muster primär?', 3, '[{"text": "Darstellung der Daten", "correct": true, "because": "View zeigt die UI an"}, {"text": "Verarbeitung der Logik", "correct": false, "because": "Aufgabe des Presenters"}, {"text": "Datenspeicherung", "correct": false, "because": "Aufgabe des Models"}]'),
('00000000-0000-0000-0000-000000000000', 'Welcher Vorteil des MVP-Musters ist am bedeutendsten?', 2, '[{"text": "Testbarkeit", "correct": true, "because": "Presenter ist unabhängig von UI testbar"}, {"text": "Hohe Performance", "correct": false, "because": "Nicht primär"}, {"text": "Geringere Kosten", "correct": false, "because": "Nicht zentral"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Rolle spielt das Model im MVP-Muster?', 2, '[{"text": "Datenverwaltung", "correct": true, "because": "Model enthält Daten und Logik"}, {"text": "Benutzerinteraktion", "correct": false, "because": "Aufgabe der View"}, {"text": "Präsentationssteuerung", "correct": false, "because": "Aufgabe des Presenters"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Problem kann im MVP-Muster auftreten, wenn die View nicht klar vom Presenter getrennt ist?', 2, '[{"text": "Schwierige Testbarkeit", "correct": true, "because": "Vermischung erschwert Unit-Tests"}, {"text": "Schnellere Entwicklung", "correct": false, "because": "Eher Verzögerung"}, {"text": "Geringere Sicherheit", "correct": false, "because": "Indirekte Folge"}]'),

-- Multiple-Choice-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Welche Komponenten gehören zum MVP-Muster?', 4, '[{"text": "Model", "correct": true, "because": "Enthält Daten und Logik"}, {"text": "View", "correct": true, "because": "Stellt UI dar"}, {"text": "Presenter", "correct": true, "because": "Steuert Interaktion"}, {"text": "Controller", "correct": false, "because": "Teil von MVC, nicht MVP"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Vorteile bietet das MVP-Muster?', 3, '[{"text": "Trennung von UI und Logik", "correct": true, "because": "Fördert Klarheit"}, {"text": "Testbarkeit", "correct": true, "because": "Presenter unabhängig testbar"}, {"text": "Wartbarkeit", "correct": true, "because": "Modulare Struktur"}, {"text": "Maximale Komplexität", "correct": false, "because": "Kein Vorteil"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Aufgaben übernimmt der Presenter im MVP-Muster?', 4, '[{"text": "Datenverarbeitung", "correct": true, "because": "Verarbeitet Model-Daten"}, {"text": "View-Updates", "correct": true, "because": "Steuert die Anzeige"}, {"text": "Benutzerinteraktion", "correct": true, "because": "Reagiert auf Eingaben"}, {"text": "Datenbankverwaltung", "correct": false, "because": "Aufgabe des Models"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Herausforderungen gibt es beim Einsatz des MVP-Musters?', 3, '[{"text": "Komplexität bei großen Views", "correct": true, "because": "Presenter kann überladen werden"}, {"text": "Abhängigkeit zwischen Presenter und View", "correct": true, "because": "Kopplung möglich"}, {"text": "Testaufwand", "correct": true, "because": "Presenter-Tests erfordern Mocking"}, {"text": "Hohe Performance", "correct": false, "because": "Kein Nachteil"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Prinzipien sollten bei der Implementierung des MVP-Musters beachtet werden?', 3, '[{"text": "Trennung von Verantwortlichkeiten", "correct": true, "because": "Klarheit zwischen Komponenten"}, {"text": "Passivität der View", "correct": true, "because": "View nur anzeigen"}, {"text": "Testbarkeit", "correct": true, "because": "Fördert Qualität"}, {"text": "Zentrale Steuerung", "correct": false, "because": "Presenter dezentral"}]'),

-- Richtig/Falsch-Kombinationsfragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Sind folgende Aussagen richtig? a) Der Presenter im MVP-Muster steuert die View. b) Die View greift direkt auf das Model zu.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Presenter ja, direkter Zugriff nein"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Das Model im MVP-Muster enthält die Geschäftslogik. b) Das MVP-Muster ist ohne UI nutzbar.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Logik ja, UI zentral"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) Die View im MVP-Muster ist passiv. b) Der Presenter ist für die Darstellung verantwortlich.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Passiv ja, Darstellung View"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind folgende Aussagen korrekt? a) MVP fördert die Testbarkeit durch den Presenter. b) Es ist immer komplexer als MVC.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Testbarkeit ja, Komplexität variabel"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) Der Presenter kann die Geschäftslogik verarbeiten. b) Die View ist im MVP-Muster aktiv und steuernd.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Logik ja, View passiv"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]');

